CREATE TABLE repairs(id INTEGER PRIMARY KEY,ticket TEXT UNIQUE,contact_id INTEGER NOT NULL REFERENCES contacts(id),device TEXT NOT NULL,identifier TEXT NOT NULL,problem TEXT NOT NULL,inspection TEXT NOT NULL,technician INTEGER REFERENCES users(id),status TEXT NOT NULL DEFAULT 'Received',diagnosis TEXT NOT NULL DEFAULT '',approved INTEGER NOT NULL DEFAULT 0,estimate INTEGER NOT NULL,final INTEGER NOT NULL DEFAULT 0,currency TEXT NOT NULL,warranty_days INTEGER NOT NULL DEFAULT 0,delivered TEXT,created TEXT NOT NULL, original_repair INTEGER REFERENCES repairs(id), closed_at TEXT);
